    fun recommendForDisease(kelas: String?): List<OralCareProduct> {
        if (kelas.isNullOrBlank()) return products.take(2)
        val normalizedInput = DiseaseDescriptions.normalize(kelas)
        return products.filter { product ->
            product.cocokUntukKelas.any { tag ->
                val normalizedTag = DiseaseDescriptions.normalize(tag)
                normalizedTag.contains(normalizedInput) || normalizedInput.contains(normalizedTag)
            }
        }.ifEmpty { products.take(2) }
    }

    fun formatRecommendationSummary(kelas: String?): String {
        val recommendations = recommendForDisease(kelas)
        return recommendations.joinToString("\n") { product ->
            "- ${product.nama}: ${product.manfaatUtama}"
        }
    }
